// Filter transaksi 7 hari terakhir (hari ini + 6 hari ke belakang), zona Asia/Jakarta
const tz = 'Asia/Jakarta';
const akhir = $now.setZone(tz).endOf('day');
const awal = akhir.minus({ days: 6 }).startOf('day');

const rupiah = (n) => 'Rp' + Number(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');

function parseTanggal(v) {
  if (v === undefined || v === null || String(v).trim() === '') return null;
  const s = String(v).trim();
  let dt = DateTime.fromFormat(s, 'd/M/yyyy', { zone: tz });
  if (!dt.isValid) dt = DateTime.fromISO(s, { zone: tz });
  return dt.isValid ? dt : null;
}

const transaksi = [];
for (const item of $input.all()) {
  const r = item.json;
  const dt = parseTanggal(r['Tanggal']);
  if (!dt) continue;                         // lewati baris kosong / tanggal tidak valid
  if (dt < awal || dt > akhir) continue;     // di luar 7 hari terakhir
  transaksi.push({
    tanggal: dt.toFormat('dd/MM/yyyy'),
    kategori: r['Kategori'] || '-',
    deskripsi: r['Deskripsi'] || '-',
    metode: r['Metode Pembayaran'] || '-',
    jumlah: Number(String(r['Jumlah (IDR)'] || '0').replace(/[^\d]/g, '')) || 0,
    penerima: r['Penerima'] || '-',
  });
}

transaksi.sort((a, b) => a.tanggal.split('/').reverse().join('').localeCompare(b.tanggal.split('/').reverse().join('')));

const totalPengeluaran = transaksi.reduce((s, t) => s + t.jumlah, 0);

const perKategori = {};
for (const t of transaksi) perKategori[t.kategori] = (perKategori[t.kategori] || 0) + t.jumlah;
const ringkasanKategori = Object.entries(perKategori)
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `- ${k}: ${rupiah(v)}`)
  .join('\n');

const dataTerformat = transaksi
  .map((t, i) => `${i + 1}. ${t.tanggal} | ${t.kategori} | ${t.deskripsi} | ${t.metode} | ${rupiah(t.jumlah)} | ${t.penerima}`)
  .join('\n');

// Selalu kembalikan 1 item agar node If tetap berjalan walau datanya kosong
return [{
  json: {
    ada_data: transaksi.length > 0,
    total_transaksi: transaksi.length,
    total_pengeluaran: totalPengeluaran,
    total_pengeluaran_rp: rupiah(totalPengeluaran),
    periode: `${awal.toFormat('dd/MM/yyyy')} - ${akhir.toFormat('dd/MM/yyyy')}`,
    ringkasan_kategori: ringkasanKategori,
    data_terformat: dataTerformat,
    transaksi,
  },
}];

